<?php
 namespace QQWorld\Setup\Controller; use QQWorld\Setup\Model\ModuleStatus; use QQWorld\Setup\Model\ObjectManagerProvider; use Zend\Mvc\Controller\AbstractActionController; use Zend\View\Model\JsonModel; use Zend\Json\Json; class Modules extends AbstractActionController { private $objectManager; protected $allModules; public function __construct(ModuleStatus $allModules, ObjectManagerProvider $objectManagerProvider) { $this->allModules = $allModules; $this->objectManager = $objectManagerProvider->get(); } public function indexAction() { $allModules = $this->allModules->getAllModules(); $enabledModules = []; foreach ($allModules as $module) { if ($module['selected']) { $enabledModules[] = $module['name']; } } $validity = $this->checkGraph($enabledModules); ksort($allModules); if ($validity->getVariable("success")) { return new JsonModel(['success' => true, 'modules' => $allModules]); } else { $errorMessage = $validity->getVariable("error"); return new JsonModel(['success' => false, 'modules' => $allModules, 'error' => '<b> Corrupt config.php!</b> <br />' . $errorMessage]); } } public function allModulesValidAction() { try { $params = Json::decode($this->getRequest()->getContent(), Json::TYPE_ARRAY); $enabledModules = isset($params['selectedModules']) ? $params['selectedModules'] : []; return $this->checkGraph($enabledModules); } catch (\Exception $e) { return new JsonModel(['success' => false, 'error' => $e->getMessage()]); } } private function checkGraph(array $toBeEnabledModules, $prettyFormat = false) { $status = $this->objectManager->create(\QQWorld\Framework\Module\Status::class); $constraints = $status->checkConstraints(true, $toBeEnabledModules, [], $prettyFormat); if ($constraints) { $message = $this->getConstraintsFailureMessage(true, $constraints); return new JsonModel(['success' => false, 'error' => $message]); } return new JsonModel(['success' => true]); } public function validateAction() { $params = Json::decode($this->getRequest()->getContent(), Json::TYPE_ARRAY); $status = $this->objectManager->create(\QQWorld\Framework\Module\Status::class); $constraints = $status->checkConstraints( $params['status'], [$params['module']], array_diff($params['selectedModules'], [$params['module']]) ); if ($constraints) { $message = $this->getConstraintsFailureMessage($params['status'], $constraints); return new JsonModel(['success' => false, 'error' => $message]); } $this->allModules->setIsEnabled($params['status'], $params['module']); $allModules = $this->allModules->getAllModules($params['selectedModules']); ksort($allModules); return new JsonModel(['modules' => $allModules]); } private function getConstraintsFailureMessage($isEnable, array $constraints) { if ($isEnable) { $updateType = 'enable'; } else { $updateType = 'disable'; } $message = " Unable to $updateType modules because of the following constraints:<br>" . PHP_EOL . implode("<br>" . PHP_EOL, $constraints); return $message; } } 